import{_ as a,C as n,o as r,c as s,E as i,a2 as o}from"./chunks/framework.Cm6XCzck.js";const b=JSON.parse('{"title":"TMPA Architecture Paper — Pre-Submission Review Draft A0.7","description":"","frontmatter":{"title":"TMPA Architecture Paper — Pre-Submission Review Draft A0.7","outline":"deep"},"headers":[],"relativePath":"en/publications/tmpa-architecture-paper-a0.7/part-01.md","filePath":"en/publications/tmpa-architecture-paper-a0.7/part-01.md","lastUpdated":1786111154000}'),l={name:"en/publications/tmpa-architecture-paper-a0.7/part-01.md"};function c(p,e,d,u,h,g){const t=n("ArticleCover");return r(),s("div",null,[i(t,{image:"/assets/covers/tmpa-paper.svg",kicker:"Research Paper",title:"TMPA Architecture Paper",summary:"An AI-native software architecture theory for governed multi-agent organizational work in SMEs.",version:"A0.7",status:"Pre-submission review draft",languageHref:"/zh/publications/tmpa-architecture-paper-a0.7",languageLabel:"简体中文"}),e[0]||(e[0]=o(`<h1 id="tmpa-textual-multi-agent-process-architecture" tabindex="-1">TMPA: Textual Multi-Agent Process Architecture <a class="header-anchor" href="#tmpa-textual-multi-agent-process-architecture" aria-label="Permalink to &quot;TMPA: Textual Multi-Agent Process Architecture&quot;">​</a></h1><h2 id="an-ai-native-software-architecture-theory-for-governed-multi-agent-organizational-work-in-smes" tabindex="-1">An AI-Native Software Architecture Theory for Governed Multi-Agent Organizational Work in SMEs <a class="header-anchor" href="#an-ai-native-software-architecture-theory-for-governed-multi-agent-organizational-work-in-smes" aria-label="Permalink to &quot;An AI-Native Software Architecture Theory for Governed Multi-Agent Organizational Work in SMEs&quot;">​</a></h2><blockquote><p><strong>Architecture Paper Draft:</strong> A0.7<br><strong>Historical Source Baseline:</strong> TMPA Draft V1.0-R23; theory aligned through R31<br><strong>Status:</strong> Pre-Submission Review Draft<br><strong>Revision Date:</strong> 2026-08-07<br><strong>Publication Authority:</strong> This GitHub document is the authoritative TMPA architecture paper. The separately maintained TMPA Core Specification is normative; the Implementation Case Report is evidentiary and non-normative.</p></blockquote><p><strong>Author:</strong> Zhu Wei, joinwell52 Research Center<br><strong>Public correspondence:</strong> <a href="https://github.com/joinwell52-AI/joinwell52" target="_blank" rel="noreferrer">joinwell52-AI/joinwell52</a><br><strong>Document identifier:</strong> TMPA-ARCH-A0.7<br><strong>Review note:</strong> This public author-identified version requires anonymization if submitted to a double-blind venue.</p><h1 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h1><p>Large language models are moving from isolated question answering into long-running, tool-using, and multi-agent execution. Tool traces and conversation histories may show what occurred, but they do not by themselves establish authorized responsibility, legal lifecycle transitions, independent review, or recoverable governance state.</p><p>This paper presents <strong>TMPA (Textual Multi-Agent Process Architecture)</strong>, an SME-first, minimal-infrastructure <strong>textual-message multi-agent asynchronous process architecture</strong>. Its core has four linked rules: <strong>text carries durable messages and state; each writer preserves a local serial stream; multiple streams progress asynchronously to form parallel collaboration; and readers aggregate the available evidence and reconstruct process, responsibility, lifecycle, conflict, and audit state</strong>. One stable primary carrier anchors each governed work item; subsequent reports, reviews, decisions, and corrections remain separate single-writer objects. Reconstruction preserves concurrency and unresolved conflict rather than imposing an artificial total order.</p><p>FCoP is the project-visible filesystem profile examined in this paper. It requires no mandatory coordination database, broker, or enterprise control plane, but it also does not by itself provide verified enterprise identity, strong role isolation, tamper-resistant storage, or Byzantine resilience. TMPA is therefore <strong>SME-first, not SME-only</strong>: larger implementations may preserve the same semantics through databases, object stores, event services, identity systems, and control planes.</p><p>Following established design-science methodology [34], [35], the study diagnoses the governance-state problem, derives design requirements, constructs the TMPA artifact, demonstrates it through the FCoP protocol profile and downstream cases, and evaluates both architectural invariants and version-pinned C01–C14 evidence. The contribution is an integrated governance architecture—not a new storage primitive, runtime, or truth oracle—and the evaluation is deliberately claim-bounded. Under the I0.6/S0.5 author-run baseline, <strong>one product criterion passes, eight remain partial, three were not run, and two fail</strong>; the separate Reference Reader passes 14 synthetic criteria. The evidence supports structural feasibility while retaining concrete implementation failures; full conformance, low-resource performance, adoption cost, comparison baselines, broader fault recovery, and third-party reproduction remain open empirical requirements.</p><p><strong>Keywords:</strong> AI governance, agentic AI, multi-agent systems, SMEs, minimal infrastructure, textual messages, primary carrier, single-writer streams, asynchronous collaboration, deterministic reconstruction, lifecycle, role separation, provenance, auditability, recoverability, FCoP, CodeFlowMu</p><hr><h1 id="_1-introduction" tabindex="-1">1. Introduction <a class="header-anchor" href="#_1-introduction" aria-label="Permalink to &quot;1. Introduction&quot;">​</a></h1><p>Large language models have transformed artificial intelligence from isolated reasoning systems into execution systems that use tools, modify files, query databases, operate business software, and collaborate over long-running tasks. Correct output remains necessary, but deployable systems must also preserve the authority, responsibility, and evidence surrounding that output.</p><p>A governed multi-agent system must answer who authorized and accepted work, which object represented it, which evidence was produced, who reviewed and decided, whether transitions were legal, and whether the process can be reconstructed after interruption. Logs, chats, workflow states, and business records may contribute evidence, but they do not automatically define an authoritative governance state.</p><p><strong>TMPA (Textual Multi-Agent Process Architecture)</strong> addresses this gap without governing how agents think or replacing agent frameworks, identity providers, runtime gateways, transports, or storage systems. It defines a cross-platform process-responsibility contract through four operational statements:</p><blockquote><p><strong>Text carries messages and state.</strong><br><strong>Each writer preserves its own serial stream.</strong><br><strong>Multiple serial streams progress asynchronously to form parallel collaboration.</strong><br><strong>Readers aggregate the streams and reconstruct process and governance state.</strong></p></blockquote><p>One stable primary carrier anchors each governed task. Acceptance, reports, reviews, decisions, corrections, and recovery evidence are independently authored objects linked by explicit references. The write side is locally serial and single-writer; the system is asynchronously parallel; the read side reconstructs a partial-order graph and issue set.</p><p>The paper uses three orientation views:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DESIGN-SCIENCE LINEAGE</span></span>
<span class="line"><span>business practice → original TMPA → FCoP extraction and maturation</span></span>
<span class="line"><span>                  → CodeFlowMu application → current TMPA formalization</span></span>
<span class="line"><span></span></span>
<span class="line"><span>CURRENT CONCEPTUAL LAYERING</span></span>
<span class="line"><span>TMPA architecture → reusable FCoP protocol profile → CodeFlowMu and other applications</span></span>
<span class="line"><span></span></span>
<span class="line"><span>END-TO-END PROCESS</span></span>
<span class="line"><span>write: primary carrier → single-writer streams → asynchronous composition</span></span>
<span class="line"><span>read:  source aggregation → governance reader → process graph + issue set</span></span></code></pre></div><p><strong>Figure 1. TMPA orientation map: historical lineage, current layering, and operational reconstruction.</strong></p><p>The lineage explains origin, the conceptual relation explains present boundaries, and the process view explains operation. None implies that FCoP exhausts TMPA, CodeFlowMu defines FCoP, or the original March 2026 pipeline already satisfied the current Core specification.</p><p>One optional application context, specified separately in Section 8.3, is a persistent AI work role sometimes described in industry as a <strong>digital employee</strong>. Throughout this paper, that label denotes only an engineering work identity that accepts delegated work, uses tools, and submits results across sessions; it does <strong>not</strong> imply legal employment, personhood, consciousness, human intention, or replacement of accountable human or organizational principals.</p><h2 id="_1-1-paper-type-and-research-questions" tabindex="-1">1.1 Paper Type and Research Questions <a class="header-anchor" href="#_1-1-paper-type-and-research-questions" aria-label="Permalink to &quot;1.1 Paper Type and Research Questions&quot;">​</a></h2><p>This paper is a design-science and systems-architecture study. The designed artifact is TMPA; the companion Core Specification defines its normative behavior, while this paper explains the problem, theory, design logic, and evaluation. The primary environment is an SME or small team in which governance must begin without assuming a dedicated agent platform, coordination database, message broker, enterprise identity plane, or specialist operations team. FCoP and CodeFlowMu provide implementation and demonstration evidence, but the study does not claim a representative benchmark, production-scale validation, or superiority over enterprise governance platforms.</p><p>The paper addresses three research questions:</p><ul><li><strong>RQ1 — Governance-state sufficiency:</strong> Which information is missing when chats, shared folders, execution traces, and ordinary task states are used as the record of multi-agent organizational work, and why does that prevent authoritative responsibility and recovery?</li><li><strong>RQ2 — Minimum architecture:</strong> Which substrate-independent objects, authority relations, lifecycle rules, ordering constraints, conflict semantics, and read-side operations are minimally necessary to reconstruct governed multi-agent work without a mandatory coordination database, broker, or control plane?</li><li><strong>RQ3 — Engineering feasibility and boundary:</strong> To what extent do the FCoP profile, CodeFlowMu, XiaoDian AI, and the pinned C01–C14 corpus demonstrate those properties, and which feasibility claims remain unsupported?</li></ul><p>A0.7 answers RQ1 through evidence-gap analysis and RQ2 through the TMPA object, stream, authority, lifecycle, and reconstruction model. RQ3 receives only a bounded answer: the reference profile and cases establish partial feasibility, while the I0.6/S0.5 baseline reports one PASS, eight PARTIAL, three NOT RUN, and two FAIL product-level criteria [28]. The WP-13 case further shows why a completed agent trajectory is not automatically admissible governance evidence [36]. Quantified setup burden, low-resource performance, broader fault recovery, comparison baselines, representative use, and third-party reproduction remain unfinished evidence.</p><p><strong>Table 1. Research claims, supporting evidence, and prohibited inference.</strong></p><table tabindex="0"><thead><tr><th>Claim</th><th>Strongest support in this study</th><th>Inference not permitted</th></tr></thead><tbody><tr><td>ordinary execution records are insufficient for governance reconstruction</td><td>problem analysis, DR1–DR8, failure and counterexample reasoning</td><td>that every chat, workflow, or event system necessarily fails</td></tr><tr><td>the TMPA object–stream–reader model is internally coherent</td><td>explicit invariants, lifecycle and authority model, determinism proof sketch, Core S0.5</td><td>a universal mathematical proof of minimality</td></tr><tr><td>a file-based protocol can realize a substantial subset</td><td>FCoP v3.2.5 mapping and author-run tests</td><td>full S0.5 conformance or protocol validity inferred from package tests</td></tr><tr><td>governed multi-agent cases can retain and qualify contested completion claims</td><td>CodeFlowMu and WP-13 evidence chains</td><td>elimination of hallucination, causal performance improvement, or independent adoption</td></tr></tbody></table><p>This matrix is the governing interpretation of the paper&#39;s contribution claims. Later implementation detail cannot enlarge a claim beyond the corresponding evidence and boundary shown here.</p><h2 id="_1-2-target-environment-and-design-constraints" tabindex="-1">1.2 Target Environment and Design Constraints <a class="header-anchor" href="#_1-2-target-environment-and-design-constraints" aria-label="Permalink to &quot;1.2 Target Environment and Design Constraints&quot;">​</a></h2><p>The primary environment is an SME or small team that needs governed AI collaboration but lacks some combination of a dedicated agent platform, coordination database, message broker, enterprise agent identity infrastructure, and specialist operations staff. This scope is defined by capability constraints, not employee count alone.</p><p>The 2026 OECD D4SME Survey reports uneven strategic and secure AI integration among more than 2,000 SMEs across 12 OECD countries, with time, maintenance cost, and skills gaps remaining material obstacles [23]. Singapore&#39;s IMDA reported 2024 AI adoption of 14.5% among SMEs versus 62.5% among non-SMEs [24]. These sources do not establish demand for TMPA specifically; they support the broader problem of responsible AI integration under constrained organizational capacity.</p><p>The design constraints lead to the following chain:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>limited infrastructure and operations capacity</span></span>
<span class="line"><span>                    ↓</span></span>
<span class="line"><span>no mandatory database, broker, cluster, or control plane</span></span>
<span class="line"><span>                    ↓</span></span>
<span class="line"><span>one governed task → one stable primary textual carrier</span></span>
<span class="line"><span>                    ↓</span></span>
<span class="line"><span>locally serial single-writer responsibility streams</span></span>
<span class="line"><span>                    ↓</span></span>
<span class="line"><span>independent streams progress asynchronously</span></span>
<span class="line"><span>                    ↓</span></span>
<span class="line"><span>source aggregation → governance reconstruction</span></span>
<span class="line"><span>                    ↓</span></span>
<span class="line"><span>recoverable process, responsibility, and audit state</span></span></code></pre></div><p><strong>Figure 2. Derivation of the minimum-infrastructure design constraints.</strong></p><blockquote><p><strong>Text-carried, locally serial, asynchronously parallel, deterministically reconstructed.</strong></p></blockquote><p>The primary profile is asynchronous project-local collaboration, not distributed consensus or multi-datacenter execution. Participants need not be online together, and evidence may arrive late; the reader exposes the authoritative, partial, disputed, or quarantined view supported by the currently available set. Database-backed and enterprise profiles remain possible, but identity federation, replication, high availability, and cross-domain enforcement are outside the present validation scope.</p><h2 id="_1-3-design-origin-and-evolution" tabindex="-1">1.3 Design Origin and Evolution <a class="header-anchor" href="#_1-3-design-origin-and-evolution" aria-label="Permalink to &quot;1.3 Design Origin and Evolution&quot;">​</a></h2><p>TMPA first appeared on 21 March 2026 in Section 7.0 of the archived multi-role architecture plan as <strong>Text-Message Multi-AI Parallel Architecture</strong> [25]. The original design joined one-task-one-carrier, files or objects as messages, asynchronous AI requests, independent task lines, role pipelines, permission checks, and audit traces.</p>`,40))])}const y=a(l,[["render",c]]);export{b as __pageData,y as default};
